# Generate the documentation pages that come from the package itself.
#
#   Rscript tools/build-docs.R
#
# Reads man/*.Rd and writes docs/reference/<file>.md, one page per help file,
# and docs/reference/index.md, grouped by the sections in
# tools/reference-index.R; rewrites the API reference part of the nav in
# mkdocs.yml from the same sections; and writes docs/releases.md from NEWS.md
# and docs/roadmap.md from ROADMAP.md. Every page it writes starts with a
# "Generated by tools/build-docs.R" comment. Run it after changing a help page,
# the sections, NEWS.md or ROADMAP.md: CI runs it again and fails if the
# committed pages differ.
#
# It uses base R only, and its output does not depend on the platform, the
# locale or the packages installed: files are written with LF line endings,
# topics are sorted in the C locale, and a link that names no package is
# resolved against this package and the packages that ship with R only.

repo <- "https://github.com/DiogoRibeiro7/heteroTests"
man_dir <- "man"
out_dir <- file.path("docs", "reference")

`%||%` <- function(x, y) if (is.null(x)) y else x

tag <- function(x) {
  attr(x, "Rd_tag") %||% ""
}

sort_c <- function(x) sort(x, method = "radix")

write_page <- function(lines, path) {
  con <- file(path, open = "wb")
  on.exit(close(con))
  writeLines(enc2utf8(lines), con, sep = "\n", useBytes = TRUE)
}

read_utf8 <- function(path) {
  readLines(path, encoding = "UTF-8", warn = FALSE)
}

# ---------------------------------------------------------------------------
# Topics

rd_files <- sort_c(list.files(man_dir, pattern = "\\.Rd$", full.names = TRUE))
parsed <- lapply(rd_files, tools::parse_Rd, encoding = "UTF-8")
# A page is named after its Rd file, as pkgdown named it: the file name is
# what roxygen makes safe (dot-diagnostic_registry.Rd), and MkDocs would skip
# a page whose name starts with a dot.
pages <- sub("\\.Rd$", "", basename(rd_files))

first_text <- function(rd, name) {
  hits <- rd[vapply(rd, tag, "") == name]
  if (length(hits) == 0L) "" else paste(unlist(hits[[1]]), collapse = "")
}

all_text <- function(rd, name) {
  vapply(rd[vapply(rd, tag, "") == name], function(a) {
    paste(unlist(a), collapse = "")
  }, "")
}

topic_names <- vapply(parsed, first_text, "", name = "\\name")
topic_aliases <- lapply(parsed, all_text, name = "\\alias")
topic_keywords <- lapply(parsed, all_text, name = "\\keyword")

# Alias (or name) -> page, the first file that has it.
local_aliases <- unlist(lapply(seq_along(parsed), function(i) {
  keys <- unique(c(topic_names[[i]], topic_aliases[[i]]))
  stats::setNames(rep(pages[[i]], length(keys)), keys)
}))
local_aliases <- local_aliases[!duplicated(names(local_aliases))]

# ---------------------------------------------------------------------------
# Links

# Only the packages that ship with R, so that a link resolves in the same way
# wherever the script runs.
base_r <- c(
  "base", "stats", "utils", "methods", "graphics", "grDevices", "datasets",
  "parallel", "tools", "grid", "splines", "stats4"
)

external_alias_index <- local({
  index <- list()
  for (pkg in base_r) {
    path <- tryCatch(find.package(pkg), error = function(e) NULL)
    if (is.null(path)) next
    aliases <- readRDS(file.path(path, "help", "aliases.rds"))
    for (alias in sort_c(names(aliases))) {
      if (is.null(index[[alias]])) index[[alias]] <- c(pkg, aliases[[alias]])
    }
  }
  index
})

external_url <- function(pkg, file) {
  if (pkg %in% base_r) {
    sprintf("https://rdrr.io/r/%s/%s.html", pkg, file)
  } else {
    sprintf("https://rdrr.io/cran/%s/man/%s.html", pkg, file)
  }
}

resolve_link <- function(target, option) {
  if (!is.null(option) && startsWith(option, "=")) {
    target <- substring(option, 2L)
    option <- NULL
  }
  if (!is.null(option)) {
    pieces <- strsplit(option, ":", fixed = TRUE)[[1]]
    pkg <- pieces[1]
    file <- if (length(pieces) > 1) pieces[2] else target
    if (pkg == "heteroTests" && !is.na(local_aliases[file])) {
      return(paste0(local_aliases[[file]], ".md"))
    }
    return(external_url(pkg, file))
  }
  if (!is.na(local_aliases[target])) {
    return(paste0(local_aliases[[target]], ".md"))
  }
  hit <- external_alias_index[[target]]
  if (!is.null(hit)) {
    return(external_url(hit[1], hit[2]))
  }
  NULL
}

url_escape <- function(url) {
  url <- gsub(" ", "%20", url, fixed = TRUE)
  url <- gsub("(", "%28", url, fixed = TRUE)
  gsub(")", "%29", url, fixed = TRUE)
}

# ---------------------------------------------------------------------------
# Rendering

escape_text <- function(x) {
  x <- gsub("\\", "\\\\", x, fixed = TRUE)
  x <- gsub("([*_`\\[\\]])", "\\\\\\1", x, perl = TRUE)
  x <- gsub("<", "&lt;", x, fixed = TRUE)
  x <- gsub(">", "&gt;", x, fixed = TRUE)
  # A dollar sign would start inline maths for pymdownx.arithmatex.
  gsub("$", "&#36;", x, fixed = TRUE)
}

code_span <- function(text) {
  text <- gsub("\n", " ", text, fixed = TRUE)
  fence <- if (grepl("`", text, fixed = TRUE)) "``" else "`"
  pad <- if (startsWith(text, "`") || endsWith(text, "`")) " " else ""
  paste0(fence, pad, text, pad, fence)
}

doi_link <- function(code) {
  doi <- regmatches(code, regexec('Rd_expr_doi\\("([^"]+)"\\)', code))[[1]]
  if (length(doi) != 2L) {
    return("")
  }
  sprintf("[doi:%s](https://doi.org/%s)", escape_text(doi[2]), url_escape(doi[2]))
}

method_usage <- function(x) {
  sprintf(
    "## S3 method for class '%s'\n%s", raw_children(x[[2]]), raw_children(x[[1]])
  )
}

raw_text <- function(x) {
  if (is.character(x)) {
    return(if (tag(x) == "COMMENT") "" else x)
  }
  switch(tag(x),
    "\\dontshow" = ,
    "\\testonly" = ,
    "\\if" = ,
    "\\out" = ,
    "USERMACRO" = ,
    "COMMENT" = "",
    "\\method" = ,
    "\\S3method" = method_usage(x),
    "\\dots" = ,
    "\\ldots" = "...",
    "\\R" = "R",
    "\\dontrun" = paste0("## Not run:\n", raw_children(x), "\n## End(Not run)"),
    raw_children(x)
  )
}

raw_children <- function(x) {
  paste(vapply(x, raw_text, ""), collapse = "")
}

# Prose: "--" and "---" are dashes, as in R's HTML help.
render_text <- function(x) {
  x <- gsub("---", intToUtf8(0x2014L), x, fixed = TRUE)
  x <- gsub("--", intToUtf8(0x2013L), x, fixed = TRUE)
  escape_text(x)
}

# Text nodes lose the indentation they have in the Rd file, which markdown
# would read as a code block; only the start of a line is trimmed.
render_children <- function(x) {
  out <- character(length(x))
  at_line_start <- TRUE
  for (i in seq_along(x)) {
    k <- x[[i]]
    piece <- if (is.character(k) && tag(k) == "TEXT") {
      text <- gsub("\n[ \t]+", "\n", k)
      if (at_line_start) text <- sub("^[ \t]+", "", text)
      render_text(text)
    } else {
      render(k)
    }
    out[[i]] <- piece
    if (nzchar(piece)) at_line_start <- endsWith(piece, "\n")
  }
  paste(out, collapse = "")
}

render_link <- function(x, as_code = FALSE) {
  label <- raw_children(x)
  target <- resolve_link(label, attr(x, "Rd_option"))
  text <- if (as_code) code_span(label) else escape_text(label)
  if (is.null(target)) text else sprintf("[%s](%s)", text, target)
}

render_code <- function(x) {
  # \code{\link{...}}, possibly followed by "()", renders as a linked code span.
  links <- Filter(function(k) tag(k) == "\\link", x)
  if (length(links) == 1L) {
    target <- resolve_link(raw_children(links[[1]]), attr(links[[1]], "Rd_option"))
    text <- code_span(trimws(raw_text(x)))
    return(if (is.null(target)) text else sprintf("[%s](%s)", text, target))
  }
  code_span(raw_text(x))
}

render_href <- function(x) {
  url <- trimws(raw_text(x[[1]]))
  text <- render(x[[2]])
  # Anchors into roxygen's R6 method sections, which this renderer drops.
  if (startsWith(url, "#")) text else sprintf("[%s](%s)", text, url_escape(url))
}

render_items <- function(x, numbered = FALSE) {
  items <- list()
  current <- NULL
  for (child in x) {
    if (tag(child) == "\\item") {
      if (!is.null(current)) items[[length(items) + 1L]] <- current
      current <- list()
    } else if (!is.null(current)) {
      current[[length(current) + 1L]] <- child
    }
  }
  if (!is.null(current)) items[[length(items) + 1L]] <- current
  lines <- vapply(seq_along(items), function(i) {
    body <- trimws(render_children(items[[i]]))
    body <- gsub("\n\\s*", " ", body)
    marker <- if (numbered) paste0(i, ".") else "-"
    paste(marker, body)
  }, "")
  paste0("\n\n", paste(lines, collapse = "\n"), "\n\n")
}

# \item{term}{description}, in \value, \describe and \arguments.
render_entry <- function(term, description) {
  desc <- tidy(render(description))
  desc <- gsub("\n", "\n    ", desc, fixed = TRUE)
  desc <- gsub("\n    \n", "\n\n", desc, fixed = TRUE)
  sprintf("\n\n%s\n:   %s\n\n", term, desc)
}

# A section is "##"; each \subsection inside it is one level further down.
subsection_depth <- 0L

render_subsection <- function(x) {
  subsection_depth <<- subsection_depth + 1L
  on.exit(subsection_depth <<- subsection_depth - 1L)
  heading <- paste(strrep("#", 2L + subsection_depth), one_line(render(x[[1]])))
  paste0("\n\n", heading, "\n\n", render(x[[2]]), "\n\n")
}

inline_maths <- function(x) {
  paste0("\\(", gsub("\\s+", " ", trimws(raw_text(x[[1]]))), "\\)")
}

display_maths <- function(x) {
  paste0("\n\n\\[\n", trimws(raw_text(x[[1]])), "\n\\]\n\n")
}

render <- function(x) {
  if (is.character(x)) {
    t <- tag(x)
    if (t == "TEXT") {
      return(render_text(x))
    }
    if (t %in% c("RCODE", "VERB")) {
      return(x)
    }
    return("")
  }
  t <- tag(x)
  switch(t,
    "\\code" = render_code(x),
    "\\verb" = ,
    "\\samp" = ,
    "\\file" = ,
    "\\env" = ,
    "\\option" = ,
    "\\command" = ,
    "\\kbd" = code_span(raw_text(x)),
    "\\link" = render_link(x),
    "\\pkg" = escape_text(raw_text(x)),
    "\\strong" = ,
    "\\bold" = paste0("**", render_children(x), "**"),
    "\\emph" = ,
    "\\var" = paste0("*", render_children(x), "*"),
    "\\dQuote" = paste0("\u201c", render_children(x), "\u201d"),
    "\\sQuote" = paste0("\u2018", render_children(x), "\u2019"),
    "\\url" = sprintf("<%s>", trimws(raw_text(x))),
    "\\href" = render_href(x),
    "\\email" = sprintf("[%s](mailto:%s)", raw_text(x), raw_text(x)),
    "\\eqn" = inline_maths(x),
    "\\deqn" = display_maths(x),
    "\\Sexpr" = doi_link(raw_children(x)),
    "\\enc" = render(x[[1]]),
    "\\R" = "R",
    "\\dots" = ,
    "\\ldots" = "...",
    "\\cr" = "  \n",
    "\\itemize" = render_items(x),
    "\\enumerate" = render_items(x, numbered = TRUE),
    "\\item" = if (length(x) == 2L) render_entry(tidy(render(x[[1]])), x[[2]]) else "",
    "\\preformatted" = paste0("\n\n```r\n", sub("^\n", "", raw_text(x)), "\n```\n\n"),
    "\\if" = ,
    "\\out" = ,
    "\\special" = ,
    "\\newcommand" = ,
    "\\renewcommand" = ,
    "USERMACRO" = ,
    "COMMENT" = "",
    "\\ifelse" = render(x[[3]]),
    "\\subsection" = render_subsection(x),
    render_children(x)
  )
}

tidy <- function(text) {
  text <- gsub("[ \t]+\n", "\n", text)
  text <- gsub("\n{3,}", "\n\n", text)
  trimws(text)
}

one_line <- function(text) {
  gsub("\\s+", " ", tidy(text))
}

section <- function(rd, name) {
  hits <- rd[vapply(rd, tag, "") == name]
  if (length(hits) == 0L) NULL else hits[[1]]
}

code_block <- function(x) {
  code <- trimws(raw_text(x), which = "right")
  code <- sub("^\n+", "", code)
  paste0("```r\n", code, "\n```")
}

render_arguments <- function(x) {
  items <- Filter(function(k) tag(k) == "\\item", x)
  entries <- vapply(items, function(item) {
    names <- trimws(strsplit(raw_text(item[[1]]), ",", fixed = TRUE)[[1]])
    term <- paste(vapply(names, code_span, ""), collapse = ", ")
    trimws(render_entry(term, item[[2]]))
  }, "")
  paste(entries, collapse = "\n\n")
}

source_file <- function(path) {
  first <- readLines(path, n = 2L, warn = FALSE)
  hit <- regmatches(first, regexpr("R/[^ ,]+\\.R", first))
  if (length(hit) == 0L) NULL else hit[[1]]
}

# The calls a usage section shows, as the index lists them: `name()`, or
# `generic(<class>)` for an S3 method.
usage_functions <- function(usage) {
  if (is.null(usage)) {
    return(character())
  }
  text <- paste(vapply(usage, function(k) {
    if (tag(k) %in% c("\\method", "\\S3method")) {
      sprintf("%s(<%s>)", raw_children(k[[1]]), raw_children(k[[2]]))
    } else {
      raw_text(k)
    }
  }, ""), collapse = "")
  calls <- regmatches(text, gregexpr(
    "(?m)^[A-Za-z_.][A-Za-z0-9_.]*(\\(<[^>]+>\\))?(?=\\()", text,
    perl = TRUE
  ))[[1]]
  calls <- unique(calls)
  ifelse(grepl("(<", calls, fixed = TRUE), calls, paste0(calls, "()"))
}

render_topic <- function(i) {
  rd <- parsed[[i]]
  name <- topic_names[[i]]
  title <- one_line(render(section(rd, "\\title")))
  parts <- c(
    "<!-- Generated by tools/build-docs.R from the Rd files: do not edit by hand. -->",
    "",
    paste("#", title),
    ""
  )
  src <- source_file(rd_files[[i]]) %||% file.path(man_dir, basename(rd_files[[i]]))
  parts <- c(parts, sprintf(
    "<small>Source: [`%s`](%s/blob/main/%s) \u00b7 Help: `?%s`</small>", src, repo, src, name
  ), "")
  add <- function(heading, body) {
    if (is.null(body) || !nzchar(body)) {
      return(invisible())
    }
    parts <<- c(parts, if (is.null(heading)) NULL else c(heading, ""), body, "")
  }
  rendered <- function(name) {
    s <- section(rd, name)
    if (is.null(s)) NULL else tidy(render(s))
  }
  add(NULL, rendered("\\description"))
  usage <- section(rd, "\\usage")
  if (!is.null(usage) && nzchar(trimws(raw_text(usage)))) {
    add("## Usage", code_block(usage))
  }
  add("## Format", rendered("\\format"))
  add("## Source", rendered("\\source"))
  arguments <- section(rd, "\\arguments")
  if (!is.null(arguments)) add("## Arguments", render_arguments(arguments))
  add("## Value", rendered("\\value"))
  add("## Details", rendered("\\details"))
  for (extra in rd[vapply(rd, tag, "") == "\\section"]) {
    add(paste("##", one_line(render(extra[[1]]))), tidy(render(extra[[2]])))
  }
  add("## Note", rendered("\\note"))
  add("## Author", rendered("\\author"))
  add("## References", rendered("\\references"))
  add("## See also", rendered("\\seealso"))
  examples <- section(rd, "\\examples")
  if (!is.null(examples)) add("## Examples", code_block(examples))
  sub("\n+$", "", paste(parts, collapse = "\n"))
}

# ---------------------------------------------------------------------------
# Sections of the reference index

sections <- source(file.path("tools", "reference-index.R"), local = new.env())$value

resolve_contents <- function(entry) {
  wanted <- entry$contents %||% character()
  unknown <- wanted[is.na(local_aliases[wanted])]
  if (length(unknown) > 0L) {
    stop("tools/reference-index.R lists unknown topics: ", paste(unknown, collapse = ", "))
  }
  found <- unname(local_aliases[wanted])
  if (!is.null(entry$keyword)) {
    has_keyword <- vapply(topic_keywords, function(k) entry$keyword %in% k, TRUE)
    found <- c(found, pages[has_keyword])
  }
  unique(found)
}

sections <- lapply(sections, function(entry) {
  entry$pages <- resolve_contents(entry)
  entry
})

missing <- setdiff(pages, unlist(lapply(sections, `[[`, "pages")))
if (length(missing) > 0L) {
  stop(
    "Help topics in no section of tools/reference-index.R: ",
    paste(missing, collapse = ", ")
  )
}

page_index <- function(page) match(page, pages)

topic_title <- function(page) {
  one_line(render(section(parsed[[page_index(page)]], "\\title")))
}

# What the index lists for a topic: its functions, or a dataset's name.
topic_functions <- function(page) {
  rd <- parsed[[page_index(page)]]
  if (identical(first_text(rd, "\\docType"), "data")) {
    return(topic_names[[page_index(page)]])
  }
  usage_functions(section(rd, "\\usage"))
}

# The nav label: `name()` for a function, the one function or method a topic
# documents, or the topic name.
topic_label <- function(page) {
  name <- topic_names[[page_index(page)]]
  fns <- topic_functions(page)
  if (paste0(name, "()") %in% fns) {
    return(paste0(name, "()"))
  }
  if (length(fns) == 1L) {
    return(fns)
  }
  name
}

render_index <- function() {
  lines <- c(
    "<!-- Generated by tools/build-docs.R from the Rd files: do not edit by hand. -->",
    "",
    "# API reference",
    "",
    "Every help topic in the package, generated from its help pages. In R, the",
    "same text is available with `?name`.",
    ""
  )
  for (entry in sections) {
    heading <- if (!is.null(entry$title)) {
      paste("##", entry$title)
    } else {
      paste("###", entry$subtitle)
    }
    lines <- c(lines, heading, "")
    if (!is.null(entry$desc)) lines <- c(lines, entry$desc, "")
    if (length(entry$pages) == 0L) next
    lines <- c(lines, "| Topic | Functions |", "| --- | --- |")
    for (page in entry$pages) {
      title <- gsub("|", "\\|", topic_title(page), fixed = TRUE)
      fns <- topic_functions(page)
      fn_text <- paste(vapply(fns, code_span, ""), collapse = ", ")
      lines <- c(lines, sprintf("| [%s](%s.md) | %s |", title, page, fn_text))
    }
    lines <- c(lines, "")
  }
  sub("\n+$", "", paste(lines, collapse = "\n"))
}

dir.create(out_dir, showWarnings = FALSE, recursive = TRUE)
unlink(list.files(out_dir, pattern = "\\.md$", full.names = TRUE))
for (i in seq_along(parsed)) {
  write_page(render_topic(i), file.path(out_dir, paste0(pages[[i]], ".md")))
}
write_page(render_index(), file.path(out_dir, "index.md"))
cat(length(parsed), "reference pages written to", out_dir, "\n")

# ---------------------------------------------------------------------------
# The API reference part of the nav in mkdocs.yml

# Material puts a nav title into the page as HTML, so the "<class>" of a method
# label would be read as a tag.
html_escape <- function(x) {
  x <- gsub("&", "&amp;", x, fixed = TRUE)
  x <- gsub("<", "&lt;", x, fixed = TRUE)
  gsub(">", "&gt;", x, fixed = TRUE)
}

yaml_quote <- function(x) {
  paste0('"', gsub('"', '\\"', gsub("\\", "\\\\", x, fixed = TRUE), fixed = TRUE), '"')
}

nav_lines <- function() {
  pad <- strrep(" ", 6L)
  lines <- paste0(pad, "- Overview: reference/index.md")
  in_title <- FALSE
  for (entry in sections) {
    if (!is.null(entry$title)) {
      depth <- 0L
      in_title <- TRUE
      label <- entry$title
    } else {
      depth <- if (in_title) 1L else 0L
      label <- entry$subtitle
    }
    indent <- paste0(pad, strrep(" ", 4L * depth))
    lines <- c(lines, paste0(indent, "- ", yaml_quote(html_escape(label)), ":"))
    for (page in entry$pages) {
      lines <- c(lines, sprintf(
        "%s    - %s: reference/%s.md", indent, yaml_quote(html_escape(topic_label(page))), page
      ))
    }
  }
  lines
}

mkdocs <- read_utf8("mkdocs.yml")
start <- grep("^ *# Generated by tools/build-docs.R", mkdocs)
end <- grep("^ *# End of the generated API reference", mkdocs)
if (length(start) != 1L || length(end) != 1L || end < start) {
  stop("mkdocs.yml needs one pair of markers around the API reference nav")
}
mkdocs <- c(mkdocs[seq_len(start)], nav_lines(), mkdocs[end:length(mkdocs)])
write_page(mkdocs, "mkdocs.yml")
cat("The API reference nav in mkdocs.yml written from tools/reference-index.R\n")

# ---------------------------------------------------------------------------
# NEWS.md and ROADMAP.md

# Python-Markdown is stricter than GitHub: a nested list needs four spaces,
# not two, and a relative link has to point at a page of the site. Lines in a
# list have their indentation doubled, and links to files in the repository
# go to GitHub.
for_mkdocs <- function(lines) {
  in_list <- FALSE
  in_fence <- FALSE
  for (i in seq_along(lines)) {
    line <- lines[[i]]
    if (!in_fence) {
      if (grepl("^([-*+]|[0-9]+[.)]) ", line)) {
        in_list <- TRUE
      } else if (grepl("^\\S", line)) {
        in_list <- FALSE
      }
    }
    if (grepl("^\\s*```", line)) in_fence <- !in_fence
    if (in_list && grepl("^ +\\S", line)) {
      lead <- attr(regexpr("^ +", line), "match.length")
      line <- paste0(strrep(" ", 2L * lead), substring(line, lead + 1L))
    }
    if (!in_fence) {
      line <- gsub(
        "\\]\\((?!https?:|mailto:|#)([^)\\s]+)\\)",
        paste0("](", repo, "/blob/main/\\1)"), line,
        perl = TRUE
      )
    }
    lines[[i]] <- line
  }
  lines
}

drop_leading_blank <- function(lines) {
  first <- which(nzchar(trimws(lines)))[1L]
  if (is.na(first)) character() else lines[first:length(lines)]
}

news <- read_utf8("NEWS.md")
if (grepl("^# ", news[[1]])) news <- news[-1L]
# The development heading is added straight after a release, before anything
# is under it; leave it off the page until it has entries.
dev <- which(news == "## Development version")
if (length(dev) == 1L) {
  following <- news[-seq_len(dev)]
  next_heading <- which(grepl("^## ", following))[1L]
  body <- if (is.na(next_heading)) following else following[seq_len(next_heading - 1L)]
  if (!any(nzchar(trimws(body)))) {
    news <- news[-seq(dev, dev + length(body))]
  }
}
write_page(c(
  "<!-- Generated by tools/build-docs.R from NEWS.md: do not edit by hand. -->",
  "",
  "# Releases",
